# introspect components by duplicating compactly
from collections import Counter
bg=Counter(v for row in D for v in row).most_common(1)[0][0]
seen=set(); comps=[]
for r in range(21):
 for c in range(10):
  if D[r][c]==bg or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   y,x=q.pop(); comp.append((y,x))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=y+dy,x+dx
     if 0<=ny<21 and 0<=nx<10 and (ny,nx) not in seen and D[ny][nx]!=bg: seen.add((ny,nx)); q.append((ny,nx))
  comps.append(comp)
print(sorted([(len(x),min(y for y,z in x),max(y for y,z in x),min(z for y,z in x),max(z for y,z in x),x[:4]) for x in comps],reverse=True))
